#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/../.." && pwd); VALIDATOR="$ROOT/skills/subagent-driven-development/scripts/sdd-coordination"
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
python3 - "$TMP" "$VALIDATOR" <<'PY'
import copy,hashlib,json,pathlib,subprocess,sys
root=pathlib.Path(sys.argv[1]); validator=sys.argv[2]; ids=['H1','H2','H3','S1','S2','S3','S4','S5','S6','C1','C2','C3']; names=['herdle','superpowers','claude-config']; gate_names=['herdle-deploy','superpowers-deploy','claude-config-deploy','cross-repository-validation']
schema=json.load(open(pathlib.Path(validator).with_name('sdd-coordination-schema.json')))
assert '$defs' in schema
assert '$defs' not in schema['properties']
def run(p,*a): return subprocess.check_output(['git','-C',str(p),*a],text=True).strip()
def digest(p): return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
repos={}
for n in names:
 p=root/n; p.mkdir(); subprocess.run(['git','init','-q',str(p)],check=True); run(p,'config','user.email','a@b'); run(p,'config','user.name','t'); (p/'source').write_text(n); subprocess.run(['git','-C',str(p),'add','.']); run(p,'commit','-qm','base'); h=run(p,'rev-parse','HEAD'); repos[n]={'repository':n,'ticket':n+'-ticket','path':str(p),'base_sha':h,'head_sha':h}
manifest=root/'expected-tasks.json'; manifest.write_text(json.dumps({'version':1,'tasks':ids},separators=(',',':'))+'\n')
tool=root/'review-package'; tool.write_text('#!/bin/sh\nexit 0\n'); tool.chmod(0o755)
dirty=root/'polytoken-container'; dirty.mkdir(); (dirty/'Dockerfile').write_text('FROM scratch\n'); subprocess.run(['git','-C',str(dirty),'init','-q'],check=True); run(dirty,'config','user.email','a@b'); run(dirty,'config','user.name','t'); subprocess.run(['git','-C',str(dirty),'add','.']); run(dirty,'commit','-qm','baseline'); status=run(dirty,'status','--short')
feature=root/'feature'; feature.mkdir(); (feature/'Dockerfile').write_text('FROM scratch\n'); subprocess.run(['git','-C',str(feature),'init','-q'],check=True); run(feature,'config','user.email','a@b'); run(feature,'config','user.name','t'); subprocess.run(['git','-C',str(feature),'add','.']); run(feature,'commit','-qm','baseline')
parity={}
for n in names:
 s=root/(n+'-source'); i=root/(n+'-installed'); s.write_text(n+'\nS7-MARKER\n'); i.write_text(n+'\nS7-MARKER\n'); parity[n]={'source':str(s),'installed':str(i),'source_sha256':digest(s),'installed_sha256':digest(i),'revision':repos[n]['head_sha'],'marker':'S7-MARKER'}
gate_evidence=[]
for gate_index in range(4):
 evidence_set={'source':{},'installed':{}}
 for n in names[:gate_index+1]:
  s=root/(str(gate_index)+'-'+n+'-gate-source'); i=root/(str(gate_index)+'-'+n+'-gate-installed'); s.write_text(n+' source\nS7-MARKER\n'); i.write_text(n+' installed\nS7-MARKER\n'); evidence_set['source'][n]={'gate':gate_names[gate_index],'repository':n,'path':str(s),'sha256':digest(s),'revision':repos[n]['head_sha'],'marker':'S7-MARKER'}; evidence_set['installed'][n]={'gate':gate_names[gate_index],'repository':n,'path':str(i),'sha256':digest(i),'revision':repos[n]['head_sha'],'marker':'S7-MARKER'}
 gate_evidence.append(evidence_set)
reviews=[{'task':i,'repository':('herdle' if i.startswith('H') else 'superpowers' if i.startswith('S') else 'claude-config'),'review':'independent-initial','approved_head':repos['herdle' if i.startswith('H') else 'superpowers' if i.startswith('S') else 'claude-config']['head_sha'],'findings':[]} for i in ids]
final=[{'repository':n,'review':'repository-final','approved_head':repos[n]['head_sha'],'findings':[],'timestamp':10+j} for j,n in enumerate(names)]
c={'version':1,'required_herdle_revision':'99b0ec512882719451a9945a94b2c44db1792472','required_herdle_binary_sha256':'eea535bfea63b17f868f9e01f071285d6f4a13e8c478fa05912d4282bfd52dde','herdle_compatibility':{'marker':'S7-MARKER','source':{'path':str(parity['herdle']['source']),'sha256':parity['herdle']['source_sha256'],'revision':'99b0ec512882719451a9945a94b2c44db1792472','binary_sha256':'eea535bfea63b17f868f9e01f071285d6f4a13e8c478fa05912d4282bfd52dde'},'installed':{'path':str(parity['herdle']['installed']),'sha256':parity['herdle']['installed_sha256'],'revision':'99b0ec512882719451a9945a94b2c44db1792472','binary_sha256':'eea535bfea63b17f868f9e01f071285d6f4a13e8c478fa05912d4282bfd52dde'}},'repositories':repos,'task_checkpoints':reviews,'final_reviews':final,'cross_repository_review':{'timestamp':13,'approved':True},'gates':[{'name':'herdle-deploy','timestamp':14,'prerequisites':[],'evidence':gate_evidence[0],'approved_revisions':{'herdle':repos['herdle']['head_sha']}},{'name':'superpowers-deploy','timestamp':15,'prerequisites':['herdle-deploy'],'evidence':gate_evidence[1],'approved_revisions':{'herdle':repos['herdle']['head_sha'],'superpowers':repos['superpowers']['head_sha']}},{'name':'claude-config-deploy','timestamp':16,'prerequisites':['herdle-deploy','superpowers-deploy'],'evidence':gate_evidence[2],'approved_revisions':{n:repos[n]['head_sha'] for n in names}},{'name':'cross-repository-validation','timestamp':17,'prerequisites':['herdle-deploy','superpowers-deploy','claude-config-deploy'],'evidence':gate_evidence[3],'approved_revisions':{n:repos[n]['head_sha'] for n in names}}], 'installed_revisions':{n:repos[n]['head_sha'] for n in names},'review_package':{'tool':'review-package','path':str(tool),'revision':digest(tool),'sha256':digest(tool)},'expected_task_manifest':{'path':'expected-tasks.json','sha256':digest(manifest)},'dirty_checkout':{'path':str(dirty),'canonical_path':str(dirty),'canonical_evidence':{'repository':'polytoken-container','path':str(dirty),'baseline_head':run(dirty,'rev-parse','HEAD'),'baseline_hash':digest(dirty/'Dockerfile')},'baseline_head':run(dirty,'rev-parse','HEAD'),'baseline_status':status,'current_status':status,'baseline_hash':digest(dirty/'Dockerfile'),'current_hash':digest(dirty/'Dockerfile'),'feature_worktree':str(feature),'feature_diff':'','unrelated_dockerfile_diff':''},'installed_source_parity':parity}
def check(label, mutate=None, diagnostic=None):
 d=copy.deepcopy(c)
 for n in ('source','installed'):
  cp=pathlib.Path(c['herdle_compatibility'][n]['path']); cp.write_text('herdle\nS7-MARKER\n'); d['herdle_compatibility'][n]['sha256']=digest(cp)
 if mutate: mutate(d)
 p=root/(label+'.json'); p.write_text(json.dumps(d)); before=p.read_bytes(); env=dict(__import__('os').environ); env.update(SDD_CANONICAL_CHECKOUT_PATH=str(dirty),SDD_CANONICAL_BASELINE_HEAD=run(dirty,'rev-parse','HEAD'),SDD_CANONICAL_BASELINE_HASH=digest(dirty/'Dockerfile')); r=subprocess.run([validator,str(p)],text=True,capture_output=True,env=env)
 for checkout,content in ((dirty,'FROM scratch\n'),(feature,'FROM scratch\n')): (checkout/'Dockerfile').write_text(content)
 if p.read_bytes()!=before: raise SystemExit(f'{label}: validator mutated artifact')
 if (diagnostic is None and r.returncode!=0) or (diagnostic is not None and (r.returncode==0 or diagnostic not in r.stderr)): raise SystemExit(f'{label}: bad result rc={r.returncode} stderr={r.stderr!r}')
 print(label)
check('coordination_accepts_complete_three_repo_contract',lambda d:None)
mutations=[('coordination_rejects_task_without_independent_review',lambda d:d['task_checkpoints'][0].update(review='other'),'task independent review invariant failed'),('coordination_rejects_missing_s6_checkpoint',lambda d:d['task_checkpoints'].pop(8),'task checkpoint set mismatch'),('coordination_rejects_extra_or_duplicate_task_id',lambda d:d['task_checkpoints'].__setitem__(0,dict(d['task_checkpoints'][1],task='X1')),'task checkpoint set mismatch'),('coordination_rejects_expected_task_manifest_checksum_drift',lambda d:d['expected_task_manifest'].__setitem__('sha256','0'*64),'expected task manifest checksum drift'),('coordination_rejects_unapproved_task_or_open_blocking_findings',lambda d:d['task_checkpoints'][0]['findings'].append({'id':'BLOCK-1','severity':'Critical'}),'task review blocking finding'),('coordination_requires_exactly_one_repo_final_review',lambda d:d['final_reviews'].pop(),'final review cardinality invariant failed'),('coordination_requires_cross_repo_review_after_all_repo_reviews',lambda d:d['cross_repository_review'].__setitem__('timestamp',2),'cross-repository review order failed'),('coordination_rejects_deployment_before_prerequisite_gate',lambda d:d['gates'][0].update(timestamp=0),'deployment prerequisite gate failed'),('coordination_requires_h_before_s_before_c_before_x',lambda d:d['gates'][1].update(timestamp=0),'gate order invariant failed'),('coordination_invalidates_downstream_gates_on_revision_drift',lambda d:d['installed_revisions'].__setitem__('herdle','0'*40),'installed revision drift invalidates dependent gates'),('coordination_requires_pinned_review_package_tool',lambda d:d['review_package'].__setitem__('sha256','0'*64),'pinned review-package tool evidence invalid'),('coordination_preserves_dirty_claude_config_checkout',lambda d:d['dirty_checkout'].__setitem__('current_hash','0'*64),'dirty checkout baseline/current status or hash drift; feature worktree unrelated Dockerfile diff'),('coordination_excludes_unrelated_dockerfile_from_feature_diff',lambda d:d['dirty_checkout'].__setitem__('unrelated_dockerfile_diff','changed'),'dirty checkout baseline/current status or hash drift; feature worktree unrelated Dockerfile diff'),('coordination_rejects_missing_installed_source_parity',lambda d:d['installed_source_parity']['superpowers'].__setitem__('installed_sha256','0'*64),'installed/source parity invariant failed'),('coordination_rejects_gate_h_revision_drift',lambda d:d.__setitem__('required_herdle_revision','0'*40),'Herdle compatibility contract drift'),('coordination_rejects_gate_h_binary_drift',lambda d:d.__setitem__('required_herdle_binary_sha256','0'*64),'Herdle compatibility contract drift'),('coordination_rejects_gate_h_marker_drift',lambda d:d['herdle_compatibility'].__setitem__('marker','wrong-marker'),'Herdle compatibility marker drift'),('coordination_rejects_unbound_gate_h_evidence',lambda d:(pathlib.Path(d['herdle_compatibility']['installed']['path']).write_text('missing-marker\n'),d['herdle_compatibility']['installed'].__setitem__('sha256',digest(pathlib.Path(d['herdle_compatibility']['installed']['path'])))),'Herdle compatibility marker drift'),('coordination_rejects_duplicate_finding_ids',lambda d:d['task_checkpoints'][0]['findings'].extend([{'id':'C1','severity':'Minor'},{'id':'C1','severity':'Minor'}]),'finding ID uniqueness invariant failed')]
for label,fn,msg in mutations:
 check(label,fn,msg)
for label,fn,msg in [
 ('coordination_rejects_stale_dependent_gate',lambda d:d['gates'][1]['approved_revisions'].__setitem__('herdle','0'*40),'gate dependency drift invalidated'),
  ('coordination_rejects_gate_wrong_repository_evidence',lambda d:d['gates'][0]['evidence']['source']['herdle'].__setitem__('repository','superpowers'),'prerequisite evidence repository binding invalid'),
  ('coordination_rejects_gate_missing_prerequisite_evidence',lambda d:d['gates'][1]['evidence']['installed'].pop('herdle'),'gate evidence dependency coverage failed'),
  ('coordination_rejects_corrupt_prerequisite_evidence_preserving_revision',lambda d:d['gates'][0]['evidence']['source']['herdle'].update(path=d['gates'][1]['evidence']['source']['herdle']['path'],sha256='0'*64,revision=d['repositories']['herdle']['head_sha'],gate='herdle-deploy',repository='herdle'),'prerequisite evidence invalid'),
  ('coordination_rejects_wrong_checkout_and_fabricated_baseline',lambda d:(d['dirty_checkout'].__setitem__('path',d['dirty_checkout']['feature_worktree']),d['dirty_checkout'].__setitem__('canonical_path',d['dirty_checkout']['feature_worktree']),d['dirty_checkout']['canonical_evidence'].update(path=d['dirty_checkout']['feature_worktree'],baseline_head=run(pathlib.Path(d['dirty_checkout']['feature_worktree']),'rev-parse','HEAD'),baseline_hash=digest(pathlib.Path(d['dirty_checkout']['feature_worktree'])/'Dockerfile'))),'trusted canonical checkout anchor mismatch'),
  ('coordination_rejects_noncanonical_identity_or_baseline',lambda d:d['dirty_checkout']['canonical_evidence'].__setitem__('repository','wrong-repository'),'trusted canonical checkout anchor mismatch'),
  ('coordination_rejects_ignored_untracked_dockerfile_drift',lambda d:((pathlib.Path(d['dirty_checkout']['feature_worktree'])/'.gitignore').write_text('*.Dockerfile\n'),(pathlib.Path(d['dirty_checkout']['feature_worktree'])/'ignored.Dockerfile').write_text('changed\n')),'dirty checkout baseline/current status or hash drift; feature worktree unrelated Dockerfile diff'),
 ('coordination_rejects_malformed_final_review',lambda d:d['final_reviews'][0].pop('timestamp'),'repository final review structure invalid'),
 ('coordination_rejects_malformed_gate',lambda d:d['gates'][0].pop('evidence'),'gate structure invalid'),
 ('coordination_rejects_malformed_cross_review',lambda d:d['cross_repository_review'].pop('approved'),'cross review structure invalid'),
 ('coordination_rejects_malformed_package',lambda d:d['review_package'].pop('tool'),'review package structure invalid'),
 ('coordination_rejects_malformed_evidence',lambda d:d['gates'][0].__setitem__('evidence','bad'),'gate structure invalid'),
 ('coordination_rejects_malformed_prerequisite_evidence_container',lambda d:d['gates'][0]['evidence'].__setitem__('source',None),'gate structure invalid'),
 ('coordination_rejects_malformed_finding',lambda d:d['task_checkpoints'][0]['findings'].append({'id':'bad_id','severity':'Minor'}),'finding ID grammar invalid'),
 ('coordination_rejects_actual_dirty_checkout_drift',lambda d:(pathlib.Path(d['dirty_checkout']['path'])/'Dockerfile').write_text('changed\\n'),'trusted canonical checkout anchor mismatch'),
 ('coordination_rejects_actual_feature_dockerfile_diff',lambda d:(pathlib.Path(d['dirty_checkout']['feature_worktree'])/'Dockerfile').write_text('changed\\n'),'feature worktree unrelated Dockerfile diff'),
]: check(label,fn,msg)
r=subprocess.run([validator],text=True,capture_output=True)
if r.returncode!=6 or 'usage: sdd-coordination ARTIFACT' not in r.stderr: raise SystemExit(f'usage: rc={r.returncode} stderr={r.stderr!r}')
print('coordination_emits_stable_usage_diagnostic')
PY
